import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"外観とテーマ","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. テーマモード（Theme Modes）","slug":"_1-テーマモード-theme-modes","link":"#_1-テーマモード-theme-modes","children":[]},{"level":2,"title":"2. テーマ選択カード","slug":"_2-テーマ選択カード","link":"#_2-テーマ選択カード","children":[{"level":3,"title":"標準・同梱テーマ一覧","slug":"標準・同梱テーマ一覧","link":"#標準・同梱テーマ一覧","children":[]},{"level":3,"title":"プラグインによるテーマの拡張","slug":"プラグインによるテーマの拡張","link":"#プラグインによるテーマの拡張","children":[]}]}],"relativePath":"ja-JP/user-guide/settings/appearance.md","filePath":"ja-JP/user-guide/settings/appearance.md","lastUpdated":1791112464000}`),a={name:`ja-JP/user-guide/settings/appearance.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="外観とテーマ" tabindex="-1">外観とテーマ <a class="header-anchor" href="#外観とテーマ" aria-label="Permalink to “外観とテーマ”">​</a></h1><p>Lertaro は、テーマモードの切り替えと複数のカラーパレットを提供します。外観設定は、設定センターの左サイドバー下部（「バージョン情報」の上）に配置されています。</p><h2 id="_1-テーマモード-theme-modes" tabindex="-1">1. テーマモード（Theme Modes） <a class="header-anchor" href="#_1-テーマモード-theme-modes" aria-label="Permalink to “1. テーマモード（Theme Modes）”">​</a></h2><p>画面上部に表示される 3 つのモードカードから選択できます。</p><ul><li><strong>ライトモード（Light）</strong>：明るいデザインに固定します。下のテーマ一覧にはライトスタイルのテーマのみが表示されます。</li><li><strong>ダークモード（Dark）</strong>：落ち着いたダークデザインに固定します。下のテーマ一覧にはダークスタイルのテーマのみが表示されます。</li><li><strong>システムに追従（Follow System）</strong>：Windows のライト/ダーク設定に応じて自動で切り替わります。このモードでは下のグリッドが <strong>ライトテーマ</strong> と <strong>ダークテーマ</strong> の 2 つに分かれ、昼と夜でそれぞれ配色を指定できます。Windows の設定変更に合わせて再起動なしでスムーズに切り替わります。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Lertaro はライトモードとダークモードで選択したテーマを個別に記憶するため、モードを切り替えても選択内容が失われることはありません。</p></div><h2 id="_2-テーマ選択カード" tabindex="-1">2. テーマ選択カード <a class="header-anchor" href="#_2-テーマ選択カード" aria-label="Permalink to “2. テーマ選択カード”">​</a></h2><p>テーマは実際の縮小プレビューカードで表示されます。検索ボックス、影、文字の視覚階層、選択ハイライトの配色が正確に再現されており、現在適用中のテーマにはチェックマークが付きます。</p><h3 id="標準・同梱テーマ一覧" tabindex="-1">標準・同梱テーマ一覧 <a class="header-anchor" href="#標準・同梱テーマ一覧" aria-label="Permalink to “標準・同梱テーマ一覧”">​</a></h3><ul><li><strong>コア内蔵テーマ（CoreExtensions）</strong>： <ul><li><strong>ライト（Light）</strong> / <strong>ダーク（Dark）</strong>：Windows のシステムスタイルに溶け込むシンプルなデザイン。</li><li><strong>ノルディックブルー（Nordic Blue）</strong>：深いネイビーとアイスブルーが調和したクールなギークスタイル。</li><li><strong>サクラピンク（Sakura Pink）</strong>：柔らかなパステルトーンの清潔感あるエレガントな配色。</li><li><strong>サイバーパンク（Cyberpunk）</strong>：ネオンイエローとミッドナイトパープルの高コントラストな近未来デザイン。</li></ul></li><li><strong>アニメテーマ（AnimeThemes、同梱）</strong>： <ul><li><strong>エヴァンゲリオン（Evangelion）</strong>、<strong>桜の開花（Sakura Blossom）</strong>、<strong>天気の子（Weathering with You）</strong>。</li></ul></li><li><strong>キュレーションテーマペア（Curated Themes、同梱）</strong>： <ul><li>ライト・ダークが対になった 20 組の配色：<strong>グレイシャー</strong>、<strong>テラコッタ</strong>、<strong>フォレスト</strong>、<strong>アメジスト</strong>、<strong>クリムゾン</strong>、<strong>グラファイト</strong>、<strong>インディゴ</strong>、<strong>ミント</strong>、<strong>シャンパン</strong>、<strong>アンバー</strong>、<strong>ロゼ</strong>、<strong>ティール</strong>、<strong>抹茶</strong>、<strong>モカ</strong>、<strong>オブシディアン</strong>、<strong>コーラルサンセット</strong>、<strong>ラベンダー</strong>、<strong>セージグリーン</strong>、<strong>パーチメント</strong>、<strong>コバルトブルー</strong>。</li></ul></li></ul><h3 id="プラグインによるテーマの拡張" tabindex="-1">プラグインによるテーマの拡張 <a class="header-anchor" href="#プラグインによるテーマの拡張" aria-label="Permalink to “プラグインによるテーマの拡張”">​</a></h3><p>すべてのテーマは <code>Lertaro.PluginSdk</code> の UI テーマ仕様に準拠しています。サードパーティ開発者は独自のテーマプラグインを作成して新しい配色を追加できます。</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};